/* Editable interface copy, including content regenerated by filters and dialogs. */
(() => {
    'use strict';
    const entries=window.IranGrains?.copy || [];
    if(!entries.length)return;
    const normal=s=>s.replace(/\s+/gu,' ').trim();
    const escape=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
    const exact=new Map(entries.filter(e=>!e.tokens.length).map(e=>[normal(e.default),e.value]));
    const patterns=entries.filter(e=>e.tokens.length).map(e=>{
        const names=[];let last=0,regex='^';
        for(const m of e.default.matchAll(/\{([^}]+)\}/g)){regex+=escape(e.default.slice(last,m.index))+'(.+?)';names.push(m[1]);last=m.index+m[0].length;}
        regex+=escape(e.default.slice(last))+'$';return{regex:new RegExp(regex,'u'),names,value:e.value};
    });
    const textState=new WeakMap(),attrState=new WeakMap();
    const excluded='#articleBody,#articleTitle,#articleCrumb,#articleBodyTitle,#articleCategory,#articleDate,#companyTitle,#companyCrumb,#companyActivity,#companyDescription,#companyManager,#companyTags,#companyBrand,#companyContacts dd,.news-card h3,.news-card .news-body p,.news-cat,.news-date,.circulars-card h3,.circulars-card p,.circulars-tag,#newsHeroTitle,#newsHeroDescription,#newsHeroDate,#newsHeroCategory,#newsFeatureTitle,#newsFeatureDescription,#newsFeatureDate,#circularDialogTitle,#circularDialogBody,#circularDialogCategory,#circularDialogDate,#homeNewsTitle,#homeNewsSummary,#homeNewsCategory,#homeNewsDate,.meet-body h3,.meet-body p,.meet-summary,.bname,.brole,.bbio,.profile-info h3,.profile-bio,.profile-role,.member-card-copy h3,.member-card-copy p,.member-activity,.company-brand b';
    function ignore(el){return !el || el.closest('script,style,svg,template,noscript,textarea,code,pre') || el.closest(excluded);}
    function translate(raw){const source=normal(raw);let value=exact.get(source);
        if(value===undefined)for(const p of patterns){const m=source.match(p.regex);if(!m)continue;const vars={};p.names.forEach((n,i)=>vars[n]=m[i+1]);value=p.value.replace(/\{([^}]+)\}/g,(all,name)=>vars[name]??all);break;}
        if(value===undefined)return raw;const spaces=raw.match(/^(\s*).*?(\s*)$/us);return(spaces?.[1]||'')+value+(spaces?.[2]||'');
    }
    function text(node){if(ignore(node.parentElement)||textState.get(node)===node.nodeValue)return;const value=translate(node.nodeValue);textState.set(node,value);if(value!==node.nodeValue)node.nodeValue=value;}
    function attrs(el){if(ignore(el))return;const state=attrState.get(el)||{};
        for(const key of ['placeholder','aria-label','title','alt']){if(!el.hasAttribute(key))continue;if(key==='alt'&&el.closest('.news-card,.member-card,.meet-card,.bphoto'))continue;const raw=el.getAttribute(key);if(state[key]===raw)continue;const value=translate(raw);state[key]=value;if(raw!==value)el.setAttribute(key,value);}
        attrState.set(el,state);
    }
    function scan(root){if(root.nodeType===Node.TEXT_NODE){text(root);return;}if(root.nodeType!==Node.ELEMENT_NODE)return;attrs(root);const walker=document.createTreeWalker(root,NodeFilter.SHOW_ELEMENT|NodeFilter.SHOW_TEXT);let n;while((n=walker.nextNode())){if(n.nodeType===Node.TEXT_NODE)text(n);else attrs(n);}}
    // Server-applied text is already current; later JavaScript replacements are
    // new nodes and therefore still receive the configured interface wording.
    document.querySelectorAll('[data-ig-static-copy]').forEach(el=>{for(const n of el.childNodes)if(n.nodeType===Node.TEXT_NODE)textState.set(n,n.nodeValue);const state={};for(const key of ['placeholder','aria-label','title','alt'])if(el.hasAttribute(key))state[key]=el.getAttribute(key);attrState.set(el,state);});
    scan(document.documentElement);
    const pending=new Set();let queued=false;
    const observer=new MutationObserver(records=>{for(const r of records){if(r.type==='childList')r.addedNodes.forEach(n=>pending.add(n));else pending.add(r.target);}if(queued)return;queued=true;queueMicrotask(()=>{queued=false;for(const node of pending)scan(node);pending.clear();});});
    observer.observe(document.documentElement,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['placeholder','aria-label','title','alt']});
})();
